from typing import Any, Dict


def flatten_dict(data: dict) -> dict:
    """Flattens nested dictionaries and lists into a single-level dictionary,

    joining keys with dots. List items use their integer index as the key component.
    Empty dicts and empty lists are preserved as values.
    Non-string keys are converted to strings using str().
    """
    result: Dict[str, Any] = {}

    def _flatten(current: Any, prefix: str) -> None:
        if isinstance(current, dict):
            if not current:
                result[prefix] = {}
            else:
                for k, v in current.items():
                    new_key = f"{prefix}.{str(k)}" if prefix else str(k)
                    _flatten(v, new_key)
        elif isinstance(current, list):
            if not current:
                result[prefix] = []
            else:
                for idx, item in enumerate(current):
                    new_key = f"{prefix}.{idx}" if prefix else str(idx)
                    _flatten(item, new_key)
        else:
            result[prefix] = current

    if not isinstance(data, dict):
        raise TypeError("Input must be a dictionary")

    if not data:
        return {}

    for key, value in data.items():
        _flatten(value, str(key))

    return result
